<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/bloodbank_v570.php';if(!bb570_enabled()){http_response_code(404);exit('Blood Bank module unavailable.');}$me=current_user();if(!$me&&function_exists('setting_bool')&&!setting_bool('bloodbank_v570_guest_donors',true)){header('Location: /login.php?next=/blood-donate.php',true,302);exit;}$banks=bb570_banks(true);$flash='';$error='';$donor=$me?bb570_my_donor((int)$me['id']):null;$campId=(int)($_GET['camp']??$_POST['camp_id']??0);$camp=$campId?bb570_camp($campId):null;$selectedBank=(int)($_GET['bank']??0);if($camp&&!empty($camp['bank_id']))$selectedBank=(int)$camp['bank_id'];$selectedGroup=bb570_validate_group((string)($_GET['group']??''));if(($_SERVER['REQUEST_METHOD']??'')==='POST'){try{csrf_check();$a=(string)($_POST['action']??'register');if($a==='register'){$id=bb570_save_public_donor($_POST,$me);$donor=['id'=>$id,'full_name'=>$_POST['full_name'],'phone'=>$_POST['phone'],'blood_group'=>$_POST['blood_group']];$flash='Donor registration received. Final donation eligibility will be confirmed by authorized blood-bank staff.';}elseif($a==='appointment'){$id=bb570_save_appointment($_POST,$me);$flash='Donation appointment requested successfully. Blood-bank staff can confirm or reschedule it.';}}catch(Throwable $e){$error=$e->getMessage();}}bb570_public_header('Donate Blood','Register as a blood donor and request a donation appointment.');?>
<main class="bb570-form-page"><section class="bb570-form-hero"><div class="bb570-shell"><span>DONATE BLOOD</span><h1>Be part of a safer local donor network.</h1><p>Register your contact and blood-group information, then choose a donation center and appointment time. Final donor eligibility is always decided by trained staff after screening.</p></div></section><div class="bb570-shell bb570-form-grid"><?php if($flash):?><div class="bb570-alert ok"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="bb570-alert err"><?=e($error)?></div><?php endif;?><?php if($camp):?><div class="bb570-alert ok" style="grid-column:1/-1"><b><?=e($camp['title'])?></b> · <?=e($camp['venue'])?> · <?=e(date('d M Y · h:i A',strtotime($camp['starts_at'])))?><?php if((int)$camp['capacity']>0):?> · <?=max(0,(int)$camp['capacity']-(int)$camp['registered_count'])?> registration places remaining<?php endif;?></div><?php endif;?><section class="bb570-form-card"><div class="form-title"><span>STEP 1</span><h2>Donor registration</h2></div><?php if($donor):?><div class="bb570-success-card"><b>Registered donor</b><strong><?=e($donor['full_name'])?> · <?=e($donor['blood_group'])?></strong><span>Your donor record is linked to this account/session workflow.</span></div><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="register"><div class="field-grid"><label>Full name<input name="full_name" required value="<?=e($me['name']??'')?>"></label><label>Phone<input name="phone" required value="<?=e($me['phone']??'')?>"></label><label>Email<input type="email" name="email" value="<?=e($me['email']??'')?>"></label><label>Blood group<select name="blood_group" required><option value="">Choose</option><?php foreach(bb570_groups() as $g):?><option <?=$selectedGroup===$g?'selected':''?>><?=e($g)?></option><?php endforeach;?></select></label><label>Date of birth<input type="date" name="date_of_birth"></label><label>Gender<select name="gender"><option value="">Prefer not to say</option><option>Male</option><option>Female</option><option>Other</option></select></label><label>Area<input name="area" placeholder="Local area"></label><label>Preferred blood bank<select name="preferred_bank_id"><option value="">Any center</option><?php foreach($banks as $b):?><option value="<?=(int)$b['id']?>" <?=$selectedBank===(int)$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach;?></select></label><label class="wide">Address<textarea name="address" rows="2"></textarea></label><label>Emergency contact name<input name="emergency_contact_name"></label><label>Emergency contact phone<input name="emergency_contact_phone"></label></div><div class="consents"><label><input type="checkbox" name="contact_opt_in" value="1" checked> I agree to be contacted about blood donation needs and appointments.</label><label><input type="checkbox" name="public_registry_opt_in" value="1"> Allow the system to count me in anonymous donor-group availability summaries.</label><label><input type="checkbox" name="consent" value="1" required> I consent to this donor record being stored for blood-bank coordination and understand that staff screening decides final eligibility.</label></div><button class="btn primary wide-btn">Register Donor</button></form><?php endif;?></section><aside class="bb570-side-note"><div class="note-icon">♥</div><h3>Privacy first</h3><p>Your name, phone, date of birth and screening information are not shown in the public donor list.</p><hr><h3>Medical screening</h3><p>The portal does not auto-approve medical eligibility. Authorized staff should complete the required history, examination, testing and local regulatory checks.</p></aside><?php if($donor):?><section class="bb570-form-card full"><div class="form-title"><span>STEP 2</span><h2>Book a donation appointment</h2></div><?php if(!$banks):?><div class="bb570-empty"><b>No donation center configured yet.</b><span>An administrator needs to add a blood bank before appointments can be booked.</span></div><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="appointment"><input type="hidden" name="camp_id" value="<?=(int)$campId?>"><input type="hidden" name="donor_id" value="<?=(int)$donor['id']?>"><input type="hidden" name="name" value="<?=e($donor['full_name'])?>"><input type="hidden" name="phone" value="<?=e($donor['phone'])?>"><input type="hidden" name="blood_group" value="<?=e($donor['blood_group'])?>"><div class="field-grid"><label>Blood bank<select name="bank_id" required><?php foreach($banks as $b):?><option value="<?=(int)$b['id']?>" <?=$selectedBank===(int)$b['id']?'selected':''?>><?=e($b['name'])?></option><?php endforeach;?></select></label><label>Preferred date & time<input type="datetime-local" name="scheduled_at" min="<?=date('Y-m-d\TH:i')?>" value="<?=$camp&&strtotime($camp['starts_at'])>=time()?e(date('Y-m-d\TH:i',strtotime($camp['starts_at']))):''?>" required></label><label class="wide">Note<textarea name="note" rows="3" placeholder="Optional note for staff"></textarea></label></div><button class="btn primary">Request Appointment</button></form><?php endif;?></section><?php endif;?></div></main><?php bb570_public_footer(); ?>
